add_shortcode( 'breadcrumbs', 'perfectpixel_breadcrumbs_html' );
add_filter( 'the_content', 'perfectpixel_breadcrumbs_auto', 5 );

function perfectpixel_breadcrumbs_items() {
	$items = array( array( '{{breadcrumbs_home}}', home_url( '/' ) ) );
	if ( is_singular() ) {
		$post = get_queried_object();
		if ( 'post' === $post->post_type ) {
			$cats = get_the_category( $post->ID );
			if ( $cats ) {
				foreach ( array_reverse( get_ancestors( $cats[0]->term_id, 'category' ) ) as $ancestor ) {
					$items[] = array( get_cat_name( $ancestor ), get_category_link( $ancestor ) );
				}
				$items[] = array( $cats[0]->name, get_category_link( $cats[0] ) );
			}
		} elseif ( is_post_type_hierarchical( $post->post_type ) ) {
			foreach ( array_reverse( get_post_ancestors( $post ) ) as $ancestor ) {
				$items[] = array( get_the_title( $ancestor ), get_permalink( $ancestor ) );
			}
		}
		$items[] = array( get_the_title( $post ), get_permalink( $post ) );
	} elseif ( is_category() || is_tag() || is_tax() ) {
		$items[] = array( single_term_title( '', false ), get_term_link( get_queried_object() ) );
	} elseif ( is_search() ) {
		$items[] = array( get_search_query(), '' );
	}
	return $items;
}

function perfectpixel_breadcrumbs_html() {
	$items = perfectpixel_breadcrumbs_items();
	if ( count( $items ) < 2 ) {
		return '';
	}
	$links = array();
	$list  = array();
	$last  = count( $items ) - 1;
	foreach ( $items as $i => $item ) {
		list( $name, $url ) = $item;
		$links[] = ( $i === $last || ! $url ) ? '<span aria-current="page">' . esc_html( wp_strip_all_tags( $name ) ) . '</span>' : '<a href="' . esc_url( $url ) . '">' . esc_html( wp_strip_all_tags( $name ) ) . '</a>';
		$list[]  = array_filter( array( '@type' => 'ListItem', 'position' => $i + 1, 'name' => wp_strip_all_tags( $name ), 'item' => $url ? $url : null ) );
	}
	$schema = array( '@context' => 'https://schema.org', '@type' => 'BreadcrumbList', 'itemListElement' => $list );
	return '<nav class="perfectpixel-breadcrumbs" aria-label="Breadcrumb" style="font-size:.9em;margin-bottom:1em">' . implode( ' ' . esc_html( '{{breadcrumbs_separator}}' ) . ' ', $links ) . '</nav>'
		. '<script type="application/ld+json">' . wp_json_encode( $schema ) . '</script>';
}

function perfectpixel_breadcrumbs_auto( $content ) {
	if ( 'yes' !== '{{breadcrumbs_auto}}' || ! is_singular( array( 'post', 'page' ) ) || is_front_page() || ! in_the_loop() || ! is_main_query() ) {
		return $content;
	}
	return perfectpixel_breadcrumbs_html() . $content;
}
